Plugins that were evaluated but scored 0 (no rules fired). These are the
    // near-misses that help diagnose why detection failed, ranked by priority.
    // Only populated if matches is empty (§3.2 step 4 failure path).
    std::vector<NearMiss> near_misses;

    //

// Result of evaluating one detection rule for diagnostic output.
struct MarkerResult
{
    std::string description;
    bool        fired = false;
};

// A plugin that was evaluated but scored 0 (no rules fired).
struct NearMiss
{
    std::string                  name;
    int                          priority = 0;
    std::vector<MarkerResult>    markers;
};

pair<std::vector<Match>, std::vector<NearMiss>> scan_directory(
    const std::filesystem::path&        root,
    const std::vector<plugin::Located>& plugins,
    const std::filesystem::path&        ast_cache,
    std::vector<std::string>&           warnings)
{
    std::vector<Match>    matches;
    std::vector<NearMiss> near_misses;
    for (const plugin::Located& located : plugins) {
        if (!located.enabled)
            continue;
        try {
            const kpl::Plugin parsed = kapc::load(located.manifest, ast_cache).plugin;
            const RuleTable   table  = compile(parsed, located.name);

            if (table.api_version > kSupportedApiVersion) {
                warnings.push_back("skipping plugin '" + table.name +
                                   "': it declares api_version " +
                                   std::to_string(table.api_version) + " but this kap supports " +
                                   std::to_string(kSupportedApiVersion));
                continue;
            }
            if (table.rules.empty())
                continue; // a plugin with no detect block claims no project

            Match match;
            match.located    = located;
            match.name       = table.name;
            match.priority   = table.priority;
            match.composable = table.composable;

            // Track each rule's result for near-miss diagnostics.
            std::vector<MarkerResult> markers;
            for (const Rule& rule : table.rules) {
                MarkerResult result;
                result.description = describe_rule(rule);
                result.fired       = evaluate(rule, root, match.matched_files);
                markers.push_back(result);
                if (result.fired)
                    ++match.score;
            }

            if (match.score > 0) {
                matches.push_back(std::move(match));
            } else {
                // Record why this plugin didn't match for diagnostic output.
                NearMiss miss;
                miss.name     = table.name;
                miss.priority = table.priority;
                miss.markers  = std::move(markers);
                near_misses.push_back(std::move(miss));
            }
        }
        catch (const diag::Error& error) {
            warnings.push_back("skipping plugin '" + located.name +
                               "': " + error.diagnostic().message);
        }
    }
    return {std::move(matches), std::move(near_misses)}

auto [matches, near_misses] =
            scan_directory(root, plugins, options.ast_cache, resolution.warnings);

        if (!matches.empty()) {
            matches = remove_superseded(matches, options.ast_cache);
        }

        if (matches.empty()) {
            // Only keep near-misses if this is the final level and nothing matched at all.
            // They are diagnostic information for explaining why detection failed.
